import java.io.*;

public class Main {
    static List<int[]> bubbleSortPasses(int[] arr) {
        // Write your solution here
        // Return a copy of the array after each of the n - 1 passes.
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            arr[i] = (int) in.nval;
        }
        StringBuilder sb = new StringBuilder();
        for (int[] s : bubbleSortPasses(arr)) {
            for (int i = 0; i < s.length; i++) sb.append(s[i]).append(i + 1 < s.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}

