def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([2, 1]), fmt([1, 2]), fmt([3, 3]), fmt([3, 2, 1]), fmt([1, 2, 3, 4]), fmt([5, 1, 4, 2]), fmt([-1, -1, -1]), fmt([9, -9, 0, 9])]
    for n in range(3, 12):
        tests.append(fmt([rng.randint(-20, 20) for _ in range(n)]))
        tests.append(fmt(rng.sample(range(-50, 50), n)))
    N = 300
    tests.append(fmt([rng.randint(-10000, 10000) for _ in range(N)]))
    tests.append(fmt(list(range(10000, 10000 - N, -1))))
    tests.append(fmt(sorted(rng.randint(-10000, 10000) for _ in range(N))))
    tests.append(fmt([rng.choice((-10000, 10000)) for _ in range(N)]))
    return tests
